/* Stage 2C (real Mednafen .mc2 save-state BAT/VRAM/CRAM)
 *
 * Generated by tools/pack_state_window.py and tools/pack_stage2c_actors.py:
 *   stage2c_state_maps.bin : 4 screens x 32x24 plane A entries
 *   stage2c_state_tiles.bin: 159 tile/palette variants converted to MD format
 *   stage2c_state_pal.bin  : 3 background lines + captured player line 3
 *   stage2c_state_actors.bin: 4 captured player frames, 2 captured fire
 *                             frames and the HUD heart tile
 */

.section .rodata
#include <macros.s>

GLABEL res_stage2c_state_tiles
.incbin "../res/gfx/stage2c_state_tiles.bin"
.align 2

GLABEL res_stage2c_state_pal
.byte 0
.byte 63
.incbin "../res/gfx/stage2c_state_pal.bin"
.align 2

GLABEL res_stage2c_state_maps
.incbin "../res/gfx/stage2c_state_maps.bin"
.align 2

GLABEL res_stage2c_state_actors
.incbin "../res/gfx/stage2c_state_actors.bin"
.align 2
